-- 390: Original BrillaPrep NSMQ subj_nsmq_math round_one beta questions (batch 001).
-- Curriculum-aligned practice content; not official NSMQ (Primetime) material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_390_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_390_guard;
INSERT INTO _migration_390_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_math_r1_b001_001' AND NOT (q.topic_id IS 'topic_nsmq_math_algebra' AND q.subject_id IS 'subj_nsmq_math' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'If 3x − 7 = 11, what is the value of x?' AND q.question_type IS 'multiple_choice' AND q.round_type IS 'round_one' AND q.options IS '["A. 6","B. 4","C. 8","D. 18"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Add 7 to both sides: 3x = 18. Divide both sides by 3: x = 6. Substitution confirms it: 3(6) − 7 = 18 − 7 = 11.' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '30' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Solve' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_math_r1_b001_001' AND NOT (r.batch_id IS 'nsmq-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_390_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_math_r1_b001_002' AND NOT (q.topic_id IS 'topic_nsmq_math_algebra' AND q.subject_id IS 'subj_nsmq_math' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Simplify the expression 2³ × 2⁴.' AND q.question_type IS 'multiple_choice' AND q.round_type IS 'round_one' AND q.options IS '["A. 32","B. 128","C. 64","D. 256"]' AND q.correct_answer IS 'B' AND q.explanation IS 'When multiplying powers with the same base, add the indices: 2³ × 2⁴ = 2⁷ = 128. A common error is multiplying the bases or the indices, giving wrong values such as 4¹².' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '30' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_math_r1_b001_002' AND NOT (r.batch_id IS 'nsmq-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_390_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_math_r1_b001_003' AND NOT (q.topic_id IS 'topic_nsmq_math_geometry' AND q.subject_id IS 'subj_nsmq_math' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the size of each exterior angle of a regular octagon?' AND q.question_type IS 'multiple_choice' AND q.round_type IS 'round_one' AND q.options IS '["A. 40°","B. 60°","C. 45°","D. 135°"]' AND q.correct_answer IS 'C' AND q.explanation IS 'The exterior angles of any convex polygon sum to 360°. A regular octagon has 8 equal exterior angles, so each is 360° ÷ 8 = 45°. (Each interior angle is then 180° − 45° = 135°.)' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '30' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_math_r1_b001_003' AND NOT (r.batch_id IS 'nsmq-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_390_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_math_r1_b001_004' AND NOT (q.topic_id IS 'topic_nsmq_math_trigonometry' AND q.subject_id IS 'subj_nsmq_math' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'If tan θ = 1 and θ is acute, what is the value of θ?' AND q.question_type IS 'multiple_choice' AND q.round_type IS 'round_one' AND q.options IS '["A. 30°","B. 60°","C. 90°","D. 45°"]' AND q.correct_answer IS 'D' AND q.explanation IS 'tan θ = sin θ / cos θ = 1 means sin θ = cos θ, which for an acute angle occurs only at θ = 45°. At 90° tangent is undefined, and at 30° and 60° it equals 1/√3 and √3 respectively.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '30' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_math_r1_b001_004' AND NOT (r.batch_id IS 'nsmq-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_nsmq_math_r1_b001_001', 'topic_nsmq_math_algebra', 'subj_nsmq_math', 'exam_nsmq', NULL, NULL, 'If 3x − 7 = 11, what is the value of x?', 'multiple_choice', 'round_one', '["A. 6","B. 4","C. 8","D. 18"]', 'A', 'Add 7 to both sides: 3x = 18. Divide both sides by 3: x = 6. Substitution confirms it: 3(6) − 7 = 18 − 7 = 11.', 'easy', '3', '1', '30', NULL, NULL, '1', NULL, NULL, 'Solve', 'AO2', NULL, NULL, NULL);
